[No burial on $[\tfrac14,\tfrac13)$] Let $\tfrac14\le p_1<\tfrac13$. Then:
\begin{enumerate}
\item[\textup{(i)}] the root is a group split: the left part
$L=\{p_1,\dots,p_k\}$ has $k\ge2$ symbols; write $a$ for its mass,
$x:=a-p_1>0$, $p_k$ for its least symbol, and $s:=|1-2a|$, so that
$s\le p_k$ by Lemma~\ref{lem:key};
\item[\textup{(ii)}] the left part splits its leader off by itself: $2p_1+p_2\ge a$;
hence $\ell_1=2$ exactly, and
\begin{equation} R\;=\;(1+a)-\mathrm H(p_1,x,1-a)\;+\;x\,R_{L'}\;+\;(1-a)\,R_{B},
\end{equation}
where $L'=L\setminus\{p_1\}$ \textup{(}mass $x$, largest symbol $p_2$, least
symbol $p_k$\textup{)} and $B$ is the right part \textup{(}mass $1-a$,
largest symbol $p_{k+1}\le p_k$\textup{)};
\item[\textup{(iii)}] the right part has at least two symbols.
\end{enumerate}

(iii) If $B=\{p_n\}$ then $1-a=p_n\le p_k\le p_1$, so $a\ge1-p_1>\tfrac12$;
the bound $s\le p_k$ forces $p_k\ge2a-1\ge1-2p_1$, and $p_k\le p_1$ then
gives $p_1\ge\tfrac13$, a contradiction.

If the left part has exactly two symbols, then
\[
\begin{aligned}
  R\;<\;\max\Bigl\{&F\bigl(p_1,\tfrac{\delta}{3}\bigr),\;
  F\bigl(p_1,\tfrac{1-p_1}{4}\bigr),\;\Theta(p_1),\\
  &N_K(p_1),\;N(p_1)\Bigr\}.
\end{aligned}
\]

On $[\tfrac14,\tfrac13]$:
\begin{enumerate}
\item[\textup{(a)}] $F(\cdot,\tfrac\delta3)\le\Theta$,
$F(\cdot,\tfrac{1-\cdot}4)\le\Theta$, and $N_K\le\Theta$;
\item[\textup{(b)}] $\Pi$ is strictly decreasing, and
$E_1,E_2,\Lambda_1,\Theta''\le\Pi(\tfrac13)\le\Pi$;
\item[\textup{(c)}] $\Lambda_2\le\Pi$ and $\Theta'\le\Pi$.
\end{enumerate}
